<?php require_once __DIR__.'/includes/bootstrap.php';if(is_logged_in())redirect('/dashboard.php');$token=$_GET['token']??$_POST['token']??'';$errors=[];$done=false;if(!is_string($token)||!preg_match('/^[a-f0-9]{64}$/',$token))$errors[]='This password reset link is invalid.';else{$s=$pdo->prepare('SELECT id,user_id FROM password_resets WHERE token_hash=? AND used_at IS NULL AND expires_at>NOW() ORDER BY id DESC LIMIT 1');$s->execute([hash('sha256',$token)]);$reset=$s->fetch();if(!$reset)$errors[]='This reset link is invalid or has expired. Request a new one.';}if($_SERVER['REQUEST_METHOD']==='POST'&&!$errors){verify_csrf();$password=$_POST['password']??'';$confirm=$_POST['confirm_password']??'';if(strlen($password)<8)$errors[]='Password must be at least 8 characters.';if($password!==$confirm)$errors[]='Passwords do not match.';if(!$errors){$pdo->beginTransaction();$s=$pdo->prepare('UPDATE users SET password_hash=? WHERE id=?');$s->execute([password_hash($password,PASSWORD_DEFAULT),$reset['user_id']]);$s=$pdo->prepare('UPDATE password_resets SET used_at=NOW() WHERE user_id=? AND used_at IS NULL');$s->execute([$reset['user_id']]);$pdo->commit();$done=true;}}$page_title='Reset password';require __DIR__.'/includes/header.php'; ?><div class="auth-wrap"><section class="panel form-panel"><h1>Reset Password</h1><?php if($done): ?><div class="alert success">Your password has been reset successfully.</div><a class="button primary" href="login.php">Return to Login</a><?php else: ?><?php foreach($errors as $err): ?><div class="alert error"><?= e($err) ?></div><?php endforeach; ?><?php if(!$errors): ?><form method="post" data-validate><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="token" value="<?= e($token) ?>"><label>New password<input type="password" name="password" required minlength="8" autocomplete="new-password"></label><label>Confirm new password<input type="password" name="confirm_password" required minlength="8" autocomplete="new-password"></label><button class="button primary" type="submit">Reset Password</button></form><?php endif; ?><p class="form-foot"><a href="login.php">Back to login</a></p><?php endif; ?></section></div><?php require __DIR__.'/includes/footer.php'; ?>